export function getMathCampaignCopy(locale: Locale): MathCampaignCopy {
  const base = copy[locale];
  const features: MathCampaignCopy["features"] = [
    { ...base.features[0], mathLabel: "ΔE / Δt", formulaLegend: formulaLegends[locale][0] },
    { ...base.features[1], formulaLegend: formulaLegends[locale][1] },
    { ...base.features[2], formulaLegend: formulaLegends[locale][2] },
    { ...base.features[3], ...portfolioCopy[locale], formulaLegend: formulaLegends[locale][3] },
  ];
  return {
    ...base,
    manifesto: [...base.manifesto, ...manifestoExtension[locale]],
    features,
    experiment: { ...base.experiment, ...experimentControls[locale] },
  };
}
